// Framework config. Pages, sidebar and colors are generated by `fw site gen`; the site address comes from FW_SITE_URL or the generated site.json.
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import sidebar from './src/generated/sidebar.json' with { type: 'json' };
import site from './src/generated/site.json' with { type: 'json' };

const url = (process.env.FW_SITE_URL || site.url).replace(/\/$/, '');
const fonts = 'https://material.aphrody.com/v1/fonts';

export default defineConfig({
  site: url,
  trailingSlash: 'always',
  integrations: [
    starlight({
      title: site.title,
      description: site.description,
      sidebar,
      social: [{ icon: 'github', label: 'GitHub', href: site.repository }],
      customCss: ['./src/generated/colors.css', './src/styles/theme.css'],
      components: { PageTitle: './src/components/PageTitle.astro' },
      credits: false,
      pagination: true,
      head: [
        { tag: 'link', attrs: { rel: 'preconnect', href: 'https://material.aphrody.com', crossorigin: '' } },
        // Font stylesheets load without blocking the first paint; font-display is swap in both files.
        { tag: 'link', attrs: { rel: 'stylesheet', href: `${fonts}/google-sans-flex.css`, media: 'print', onload: "this.media='all'" } },
        { tag: 'link', attrs: { rel: 'stylesheet', href: `${fonts}/google-sans-code.css`, media: 'print', onload: "this.media='all'" } },
        { tag: 'meta', attrs: { property: 'og:image', content: `${url}/og.png` } },
        { tag: 'meta', attrs: { property: 'og:image:width', content: '1200' } },
        { tag: 'meta', attrs: { property: 'og:image:height', content: '630' } },
        { tag: 'meta', attrs: { property: 'og:image:alt', content: site.ogImageAlt } },
        { tag: 'meta', attrs: { name: 'twitter:image', content: `${url}/og.png` } },
      ],
    }),
  ],
});
